#include <iostream>
struct N { int v; N* l; N* r; };
void in(N* p) {
    if (!p) return;
    in(p->l); std::cout << p->v; in(p->r);
}
int main() {
    N b{2, 0, 0}, c{3, 0, 0}, a{1, &b, &c};
    in(&a);
}

