#include <iostream>
#include <queue>
struct N { int v; N* l; N* r; };
int main() {
    N d{4, 0, 0}, c{3, 0, 0}, b{2, &d, 0}, a{1, &b, &c};
    std::queue<N*> q; q.push(&a);
    while (!q.empty()) {
        N* p = q.front(); q.pop();
        std::cout << p->v;
        if (p->l) q.push(p->l); if (p->r) q.push(p->r);
    }
}

#include <iostream>
struct N { int v; N* l; N* r; };
int sum(N* p) {
    if (!p) return 0;
    return p->v + sum(p->l) + sum(p->r);
}
int main() {
    N d{4, 0, 0}, c{3, 0, 0}, b{2, &d, 0}, a{1, &b, &c};
    std::cout << sum(&a);
}

#include <iostream>
struct N { int v; N* l; N* r; };
void walk(N* p) {
    if (!p) return;
    walk(p->l);
    walk(p->r);
    std::cout << p->v;
}
